function isSingleMountain(arr: number[]): boolean {
  const n = arr.length;
  let i = 0, j = n - 1;
  while (i + 1 < n && arr[i] < arr[i + 1]) i++;
  while (j > 0 && arr[j - 1] > arr[j]) j--;
  return i > 0 && j < n - 1 && i === j;
}

